# Prove the OLD design deadlocks under the same concurrent handoff/claim load.
import threading, time
class OldPool:
    def __init__(self):
        self._queue_lock = threading.Lock()
        self._report_lock = threading.Lock()
        self._queue = list(range(500))
        self._reports = {}
    def handoff(self, w, r):
        with self._report_lock:
            with self._queue_lock:
                self._reports[w] = r
                if self._queue: return self._queue.pop(0)
        return None
    def claim(self, w):
        with self._queue_lock:
            with self._report_lock:
                self._reports.setdefault(w, None)
                if self._queue: return self._queue.pop(0)
        return None
p = OldPool()
stop = threading.Event()
def h():
    while not stop.is_set(): p.handoff("h","r")
def c():
    while not stop.is_set(): p.claim("c")
ts=[threading.Thread(target=h) for _ in range(8)]+[threading.Thread(target=c) for _ in range(8)]
for t in ts: t.start()
time.sleep(1)
stop.set()
hung=[t for t in ts if t.join(3)]
print("OLD design: %d of %d threads hung after stop" % (len(hung), len(ts)))
EOF

