# Bounded proof that the OLD two-lock design deadlocks under the same
# concurrent handoff/claim load. (Bounded so this can't hang.)
import threading, time
class OldPool:
    def __init__(self):
        self._ql = threading.Lock(); self._rl = threading.Lock()
        self._queue = list(range(1000)); self._reports = {}
    def handoff(self, w, r):
        with self._rl:
            with self._ql:
                self._reports[w] = r
                if self._queue: return self._queue.pop(0)
        return None
    def claim(self, w):
        with self._ql:
            with self._rl:
                self._reports.setdefault(w, None)
                if self._queue: return self._queue.pop(0)
        return None
p = OldPool()
stop = threading.Event()
def h():
    while not stop.is_set(): p.handoff("h","r")
def c():
    while not stop.is_set(): p.claim("c")
ts=[threading.Thread(target=h,daemon=True) for _ in range(4)]+[threading.Thread(target=c,daemon=True) for _ in range(4)]
for t in ts: t.start()
time.sleep(1)
stop.set()
hung=[t for t in ts if t.join(3)]
print("OLD design: %d of %d worker threads still hung after stop" % (len(hung), len(ts)))
